(function () {
  "use strict";

  var config = window.TIKEE_CONFIG || {};
  var msalClient = null;
  var activeAccount = null;
  var resolvedSite = null;
  var resolvedDrive = null;

  function configured() {
    return (
      /^[0-9a-f-]{36}$/i.test(config.tenantId || "") &&
      /^[0-9a-f-]{36}$/i.test(config.spaClientId || "") &&
      /^[a-z0-9.-]+\.sharepoint\.com$/i.test(
        config.sharePointHostname || ""
      ) &&
      /^\/sites\/[^/]+/i.test(config.sharePointSitePath || "") &&
      Boolean(config.documentLibrary) &&
      Boolean(config.dataRoot) &&
      Boolean(config.dashboardFile)
    );
  }

  function escapeHtml(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function status(kind, title, detail) {
    var host = document.getElementById("tikeeBackendStatus");
    if (!host) return;
    host.className = "backend-status " + kind;
    host.innerHTML =
      '<div class="backend-status-dot"></div><div><strong>' +
      escapeHtml(title) +
      "</strong><span>" +
      escapeHtml(detail || "") +
      "</span></div>";
  }

  function setIdentity(account) {
    var host = document.getElementById("tikeeBackendIdentity");
    if (!host) return;
    host.innerHTML = account
      ? "<strong>" +
        escapeHtml(account.name || account.username || "Usuario Microsoft 365") +
        "</strong><span>" +
        escapeHtml(account.username || "") +
        "</span>"
      : "";
  }

  function redirectUri() {
    return window.location.origin + window.location.pathname;
  }

  async function initializeMsal() {
    if (!window.msal || !window.msal.PublicClientApplication) {
      throw new Error(
        "No se cargó Microsoft Authentication Library. Verifica vendor/msal-browser.min.js."
      );
    }
    if (msalClient) return;
    msalClient = new window.msal.PublicClientApplication({
      auth: {
        clientId: config.spaClientId,
        authority:
          "https://login.microsoftonline.com/" +
          encodeURIComponent(config.tenantId),
        redirectUri: redirectUri(),
        postLogoutRedirectUri: redirectUri()
      },
      cache: {
        cacheLocation: "sessionStorage"
      }
    });
    await msalClient.initialize();
    var redirectResult = await msalClient.handleRedirectPromise();
    activeAccount =
      (redirectResult && redirectResult.account) ||
      msalClient.getActiveAccount() ||
      msalClient.getAllAccounts()[0] ||
      null;
    if (activeAccount) msalClient.setActiveAccount(activeAccount);
  }

  function loginOverlay(message) {
    var existing = document.getElementById("tikeeLoginOverlay");
    if (existing) {
      var existingMessage = document.getElementById("tikeeLoginMessage");
      if (existingMessage && message) existingMessage.textContent = message;
      return;
    }
    var overlay = document.createElement("div");
    overlay.id = "tikeeLoginOverlay";
    overlay.className = "tikee-login-overlay";
    overlay.innerHTML =
      '<div class="tikee-login-card">' +
      '<div class="tikee-login-brand"><div>t</div><span>TIKEE.TECH</span></div>' +
      "<h2>Tikee Adoption 360</h2>" +
      "<p>La información permanece protegida en SharePoint. Accede con tu cuenta institucional de Microsoft 365.</p>" +
      '<div id="tikeeLoginMessage" class="tikee-login-message">' +
      escapeHtml(message || "") +
      "</div>" +
      '<button id="tikeeLoginButton" type="button">Continuar con Microsoft 365</button>' +
      "</div>";
    document.body.appendChild(overlay);
    document
      .getElementById("tikeeLoginButton")
      .addEventListener("click", async function () {
        var button = document.getElementById("tikeeLoginButton");
        var messageHost = document.getElementById("tikeeLoginMessage");
        button.disabled = true;
        button.textContent = "Abriendo Microsoft 365…";
        messageHost.textContent = "";
        try {
          var result = await msalClient.loginPopup({
            scopes: config.graphScopes,
            prompt: "select_account"
          });
          activeAccount = result.account;
          msalClient.setActiveAccount(activeAccount);
          overlay.remove();
          await loadDashboard();
        } catch (error) {
          messageHost.textContent =
            error && error.message
              ? error.message
              : "No fue posible iniciar la sesión.";
        } finally {
          button.disabled = false;
          button.textContent = "Continuar con Microsoft 365";
        }
      });
  }

  async function accessToken() {
    if (!activeAccount) throw new Error("La sesión de Microsoft 365 no está activa.");
    var request = {
      account: activeAccount,
      scopes: config.graphScopes
    };
    try {
      return (await msalClient.acquireTokenSilent(request)).accessToken;
    } catch (_) {
      return (await msalClient.acquireTokenPopup(request)).accessToken;
    }
  }

  async function graphJson(path, token) {
    var response = await fetch(
      /^https:\/\//i.test(path)
        ? path
        : "https://graph.microsoft.com/v1.0" + path,
      {
        headers: {
          Authorization: "Bearer " + token,
          Accept: "application/json"
        }
      }
    );
    var payload = await response.json().catch(function () {
      return {};
    });
    if (!response.ok) {
      var detail =
        payload &&
        payload.error &&
        (payload.error.message || payload.error.code);
      throw new Error(
        detail ||
          "Microsoft Graph respondió con código " + String(response.status) + "."
      );
    }
    return payload;
  }

  async function resolveSharePoint(token) {
    if (!resolvedSite) {
      resolvedSite = await graphJson(
        "/sites/" +
          config.sharePointHostname +
          ":" +
          config.sharePointSitePath +
          "?$select=id,displayName,webUrl",
        token
      );
    }
    if (!resolvedDrive) {
      var drives = await graphJson(
        "/sites/" +
          encodeURIComponent(resolvedSite.id) +
          "/drives?$select=id,name,webUrl",
        token
      );
      resolvedDrive = (drives.value || []).find(function (drive) {
        return (
          String(drive.name || "").toLowerCase() ===
          String(config.documentLibrary || "").toLowerCase()
        );
      });
      if (!resolvedDrive) {
        throw new Error(
          'No se encontró la biblioteca "' +
            config.documentLibrary +
            '" en el sitio configurado.'
        );
      }
    }
  }

  async function downloadDashboard(token) {
    await resolveSharePoint(token);
    var cleanPath = [config.dataRoot, config.dashboardFile]
      .join("/")
      .replace(/^\/+|\/+$/g, "");
    var response = await fetch(
      "https://graph.microsoft.com/v1.0/drives/" +
        encodeURIComponent(resolvedDrive.id) +
        "/root:/" +
        cleanPath
          .split("/")
          .map(encodeURIComponent)
          .join("/") +
        ":/content",
      {
        headers: {
          Authorization: "Bearer " + token,
          Accept: "application/json"
        }
      }
    );
    var payload = await response.json().catch(function () {
      return {};
    });
    if (!response.ok) {
      var detail =
        payload &&
        payload.error &&
        (payload.error.message || payload.error.code);
      throw new Error(
        detail ||
          "No se pudo descargar el consolidado de SharePoint (" +
            response.status +
            ")."
      );
    }
    return payload;
  }

  function monthSort(left, right) {
    var order = {
      enero: 1,
      febrero: 2,
      marzo: 3,
      abril: 4,
      mayo: 5,
      junio: 6,
      julio: 7,
      agosto: 8,
      septiembre: 9,
      octubre: 10,
      noviembre: 11,
      diciembre: 12
    };
    function parts(value) {
      var p = String(value).toLowerCase().split(" ");
      return { month: order[p[0]] || 0, year: Number(p[1]) || 0 };
    }
    var a = parts(left);
    var b = parts(right);
    return a.year === b.year ? a.month - b.month : a.year - b.year;
  }

  function renderIngestions(items) {
    var host = document.getElementById("tikeeIngestionLog");
    if (!host) return;
    if (!items || !items.length) {
      host.innerHTML =
        '<div class="backend-empty">Todavía no existen correos procesados.</div>';
      return;
    }
    host.innerHTML =
      '<div class="backend-ingestion-head"><span>Fecha</span><span>Estado</span><span>Filas</span><span>Observación</span></div>' +
      items
        .slice(0, 20)
        .map(function (item) {
          var rows =
            Number(item.rows_users || 0) +
            Number(item.rows_transfers || 0) +
            Number(item.rows_service_payments || 0);
          var note =
            item.error_message ||
            ((item.warnings || []).length
              ? item.warnings.join(" · ")
              : "Procesamiento correcto");
          return (
            '<div class="backend-ingestion-row"><span>' +
            escapeHtml(item.report_date || item.received_at || item.processed_at) +
            '</span><span><b class="backend-pill ' +
            escapeHtml(item.status || "processed") +
            '">' +
            escapeHtml(item.status || "processed") +
            "</b></span><span>" +
            rows.toLocaleString("es-EC") +
            "</span><span>" +
            escapeHtml(note) +
            "</span></div>"
          );
        })
        .join("");
  }

  function applyPayload(payload) {
    window.datosHistoricos = payload.monthly || {};
    datosHistoricos = window.datosHistoricos;
    Object.keys(datosHistoricos).forEach(function (month) {
      var data = datosHistoricos[month];
      data.origenes = new Set(
        Array.isArray(data.origenes)
          ? data.origenes
          : (data.cooperativas || []).map(function (row) {
              return row.origen;
            })
      );
    });
    var months = Object.keys(datosHistoricos).sort(monthSort);
    window.datosMesActual = months.length
      ? datosHistoricos[months[months.length - 1]]
      : null;
    datosMesActual = window.datosMesActual;
    window._datosActualizados = true;

    if (typeof window.tikeeSetDailyData === "function") {
      window.tikeeSetDailyData(payload.daily || {});
    } else {
      window.TIKEE_DIARIO_DATA = payload.daily || {};
    }
    if (typeof window.v41EnsureConfigs === "function") window.v41EnsureConfigs();
    if (typeof window.actualizarMesFilter === "function")
      window.actualizarMesFilter();
    if (typeof window.actualizarOrigenFilters === "function")
      window.actualizarOrigenFilters();
    if (typeof window.actualizarDatosTable === "function")
      window.actualizarDatosTable();
    if (typeof window.v41RenderQuality === "function") window.v41RenderQuality();
    if (
      document.getElementById("dashboard") &&
      document.getElementById("dashboard").classList.contains("active") &&
      typeof window.actualizarDashboard === "function"
    ) {
      window.actualizarDashboard();
    }

    renderIngestions(payload.ingestions || []);
    setIdentity(activeAccount);

    var generatedAt = payload.generated_at
      ? new Date(payload.generated_at)
      : new Date();
    var lastSync = document.getElementById("tikeeLastSync");
    if (lastSync) {
      lastSync.textContent = generatedAt.toLocaleString("es-EC", {
        dateStyle: "medium",
        timeStyle: "short"
      });
    }
    var periodCount = document.getElementById("tikeePeriodCount");
    if (periodCount) periodCount.textContent = String(months.length);
    var dayCount = document.getElementById("tikeeDayCount");
    if (dayCount)
      dayCount.textContent = String(Object.keys(payload.daily || {}).length);
  }

  async function loadDashboard() {
    if (!activeAccount) {
      status(
        "warning",
        "Sesión requerida",
        "Accede con tu cuenta institucional de Microsoft 365."
      );
      loginOverlay();
      return;
    }
    status(
      "loading",
      "Sincronizando",
      "Consultando el consolidado protegido en SharePoint…"
    );
    var token = await accessToken();
    var payload = await downloadDashboard(token);
    applyPayload(payload);
    status(
      "success",
      "SharePoint sincronizado",
      Object.keys(payload.daily || {}).length +
        " días disponibles · actualización automática desde Outlook y Claude"
    );
  }

  window.tikeeBackendReload = async function () {
    try {
      await loadDashboard();
      if (typeof window.mostrarMensaje === "function") {
        window.mostrarMensaje(
          "success",
          "Información actualizada desde SharePoint."
        );
      }
    } catch (error) {
      status("error", "Error de sincronización", error.message);
      if (typeof window.mostrarMensaje === "function") {
        window.mostrarMensaje("error", error.message);
      }
    }
  };

  window.tikeeBackendLogout = async function () {
    setIdentity(null);
    if (msalClient && activeAccount) {
      await msalClient.logoutPopup({
        account: activeAccount,
        postLogoutRedirectUri: redirectUri(),
        mainWindowRedirectUri: redirectUri()
      });
    }
    activeAccount = null;
    loginOverlay("Sesión cerrada.");
  };

  async function init() {
    if (!configured()) {
      status(
        "warning",
        "Conexión pendiente de configurar",
        "Completa los identificadores de Microsoft Entra y SharePoint antes de publicar."
      );
      var setup = document.getElementById("tikeeSetupNotice");
      if (setup) setup.style.display = "block";
      return;
    }
    try {
      await initializeMsal();
      await loadDashboard();
    } catch (error) {
      status("error", "Error de conexión", error.message);
      if (!activeAccount) loginOverlay(error.message);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
